library(creditratingsystem)
for(name in c('.cm_predict_pd','.cf_gam_raw','.cf_boost_raw'))if(!exists(name))assign(name,getFromNamespace(name,'creditratingsystem'))
target<-list(event='default',horizon=1,time_unit='years',probability_measure='PHYSICAL',conditioning='performing')
meta<-list(target=target,training=list(data_fingerprint='flexible-analytic',split_id='train',known_at='2025-01-01',data_origin='SYNTHETIC'),model_id='flexible',model_version='1')
fit<-function(fun,...)do.call(fun,c(list(...),meta))
pred<-function(m,x)unlist(predict_pd(m,x,feature_order='x',expected_target=target)$value)
close<-function(a,b,tol=1e-6)stopifnot(max(abs(a-b))<tol)
error<-function(expr,code){e<-tryCatch({force(expr);NULL},error=function(e)e);stopifnot(inherits(e,'error'),identical(e$code,code))}
x<-matrix(-3:3,ncol=1);y<-c(0,1,0,1,0,1,1)
g<-fit(fit_gam_pd,x,y,feature_order='x',linear_features='x',smooth_specs=list(),variant='unconstrained')
m<-fit(fit_binary_glm,x,y,feature_order='x',fit_intercept=TRUE,link='logit')
close(unlist(g$model$parameters$coefficients),unlist(m$model$parameters$coefficients));close(g$diagnostics$effective_degrees_of_freedom,2)
smooth<-function(mono='increasing',extra='error')list(feature='x',boundary_knots=c(-2,2),interior_knots=c(-1,0,1),degree=3L,smoothing=.02,monotonicity=mono,extrapolation=extra)
x<-matrix(rep(seq(-2,2,length.out=9),each=8),ncol=1);y<-unlist(lapply(c(1,1,2,3,4,5,6,7,7),function(i)as.integer(0:7<i)))
m<-fit(fit_gam_pd,x,y,feature_order='x',linear_features=character(),smooth_specs=list(smooth()),variant='monotone');grid<-matrix(seq(-2,2,length.out=301),ncol=1)
stopifnot(min(.cf_gam_raw(m$model,grid,'x',derivative_feature='x'))>=-1e-12,min(diff(pred(m,grid)))>=-1e-12)
dec<-fit(fit_gam_pd,x,y,feature_order='x',linear_features=character(),smooth_specs=list(smooth('decreasing')),variant='monotone')
close(pred(dec,grid),rep(mean(y),301));stopifnot(dec$diagnostics$active_constraint_count>0)
error(pred(m,matrix(3,ncol=1)),'OUTSIDE_SUPPORT')
plan<-function(indices,features=list(root=list(0),L=list(0),R=list(0)))list(sample_indices=as.list(indices),node_features=features)
x<-matrix(0:3,ncol=1);y<-c(0,0,1,1)
for(criterion in c('gini','log_loss')) {
 m<-fit(fit_random_forest_pd,x,y,feature_order='x',sampling_plan=list(plan(0:3),plan(c(0,0,2,2))),max_depth=1L,criterion=criterion)
 close(pred(m,x),c(0,0,1,1));stopifnot(m$model$parameters$trees[[1]]$threshold==1.5,identical(unlist(m$diagnostics$oob_counts),c(0L,1L,0L,1L)),m$diagnostics$oob_brier==0)
}
m<-fit(fit_random_forest_pd,x,c(0,1,0,1),feature_order='x',sampling_plan=list(plan(0:3)),max_depth=1L,min_samples_leaf=3L,weights=c(1,3,2,2))
close(pred(m,x),rep(5/8,4))
x<-matrix(rep(c(-1,1),each=4),ncol=1);y<-rep(0:1,each=4)
m<-fit(fit_gradient_boosting_pd,x,y,feature_order='x',train_row_ids=as.character(0:7),iterations=1L,max_depth=1L,learning_rate=.3,l2_regularization=1,min_child_weight=0)
close(.cf_boost_raw(m$model,matrix(c(-1,1),ncol=1),'x'),c(-.3,.3),2e-8)
x<-matrix(seq(-2,2,length.out=40),ncol=1);y<-rep(0:1,20)
inner<-list(X=x,y=1-y,row_ids=paste0('v',0:39),role='inner_validation',split_id='inner',known_at='2024-12-31')
m<-fit(fit_gradient_boosting_pd,x,y,feature_order='x',train_row_ids=as.character(0:39),iterations=30L,max_depth=2L,learning_rate=.3,min_child_weight=0,inner_validation=inner,early_stopping_rounds=2L,monotonic_constraints=1)
stopifnot(m$diagnostics$selected_iterations<30,min(diff(pred(m,matrix(seq(-2,2,length.out=101),ncol=1))))>=-1e-12)
if(!exists('.cf_gam_spline')) .cf_gam_spline<-getFromNamespace('.cf_gam_spline','creditratingsystem')
t<-seq(0,1,length.out=17);spec<-list(full_knots=as.list(c(rep(0,4),rep(1,4))),degree=3,coefficient_transform=lapply(seq_len(4),function(i)as.list(rbind(rep(0,3),diag(3))[i,])),extrapolation='error')
close(.cf_gam_spline(t,spec),cbind(3*t*(1-t)^2,3*t*t*(1-t),t^3),1e-14)
for(mono in c('none','increasing'))error(fit(fit_gam_pd,matrix(c(-2,-1,1,2),ncol=1),c(0,0,1,1),feature_order='x',linear_features=character(),smooth_specs=list(smooth(mono)),variant=if(mono=='none')'unconstrained' else 'monotone'),'SEPARATION')
